  WHEN `category` IN ('衣物') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手提袋%') THEN '箱包行李'
  WHEN `category` IN ('衣物') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%u型枕%') THEN '生活用品'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%背包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%双肩包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%书包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%行李箱%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%拉杆箱%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手提包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%挎包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%公文包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%腰包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%皮箱%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%箱子%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%布兜%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手提袋%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手提箱%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%男士包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%电脑包%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%小包%') THEN '箱包行李'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%钱包%') THEN '钱包卡包'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%包%') THEN '箱包行李'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手表%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%眼镜%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%戒指%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%手链%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%项链%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%首饰%') THEN '服饰配饰'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%伞%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%杯子%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%水杯%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%水壶%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%药物%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%口罩%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%玩具%') THEN '生活用品'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%宠物%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%小狗%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%暹罗%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%公鸡%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%小猫%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%猫%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%兔子%') THEN '宠物活体'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%u盘%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%优盘%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%耳机%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%充电宝%') THEN '数码电子'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%火车票%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%号牌%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%车牌%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%票据%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%发票%') THEN '卡券票据'
  WHEN `category` IN ('其他') AND (LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%身份证%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%户口%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%营业执照%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%护照%' OR LOWER(REPLACE(REPLACE(REPLACE(REPLACE(`title`, ' ', ''), CHAR(9), ''), CHAR(10), ''), CHAR(13), '')) LIKE '%毕业证%') THEN '证件证照'
  WHEN `category` = '证件' THEN '证件证照'
  WHEN `category` = '钥匙' THEN '钥匙锁具'
  WHEN `category` = '手机' THEN '手机通讯'
  WHEN `category` = '电子产品' THEN '数码电子'
  WHEN `category` = '钱包' THEN '钱包卡包'
  WHEN `category` = '书籍' THEN '书刊文件'
  WHEN `category` = '衣物' THEN '服饰配饰'
  WHEN `category` = '其他' THEN '其他'
  ELSE `category`
END
WHERE `category` IN ('证件','钥匙','手机','电子产品','钱包','书籍','衣物','其他');

-- 兜底：任何不在新字典中的残留值统一归 其他
UPDATE `found` SET `category`='其他' WHERE `category` NOT IN ('证件证照','卡券票据','手机通讯','数码电子','服饰配饰','钥匙锁具','钱包卡包','箱包行李','书刊文件','生活用品','宠物活体','其他');

-- 兜底：任何不在新字典中的残留值统一归 其他
UPDATE `lost` SET `category`='其他' WHERE `category` NOT IN ('证件证照','卡券票据','手机通讯','数码电子','服饰配饰','钥匙锁具','钱包卡包','箱包行李','书刊文件','生活用品','宠物活体','其他');

-- 【3】校验：非法类别必须为 0，且各新类别之和等于总行数
SELECT `category`, COUNT(*) AS cnt FROM `found` GROUP BY `category` ORDER BY cnt DESC;
SELECT COUNT(*) AS illegal FROM `found` WHERE `category` NOT IN ('证件证照','卡券票据','手机通讯','数码电子','服饰配饰','钥匙锁具','钱包卡包','箱包行李','书刊文件','生活用品','宠物活体','其他');

SELECT `category`, COUNT(*) AS cnt FROM `lost` GROUP BY `category` ORDER BY cnt DESC;
SELECT COUNT(*) AS illegal FROM `lost` WHERE `category` NOT IN ('证件证照','卡券票据','手机通讯','数码电子','服饰配饰','钥匙锁具','钱包卡包','箱包行李','书刊文件','生活用品','宠物活体','其他');

COMMIT;

-- 【4】回滚模板（仅在 found/lost 行数与快照一致时执行；有新增业务行时禁止直接回滚）
START TRANSACTION;
UPDATE `found` f JOIN `category_redesign_bak_<SUFFIX>_found` s ON f.`id`=s.`id` SET f.`category`=s.`category`;
UPDATE `lost` f JOIN `category_redesign_bak_<SUFFIX>_lost` s ON f.`id`=s.`id` SET f.`category`=s.`category`;
COMMIT;

